export function getMockJobs(now = Date.now()): Job[] {
  return seeds.map(
    (
      [
        title,
        companyIndex,
        category,
        location,
        city,
        workType,
        experience,
        min,
        max,
        currency,
        tech,
        hours,
        preview,
      ],
      index,
    ) => {
      const [name, initials, color, background, website, companyDescription] =
        companies[companyIndex];
      const eligibility =
        location === "Worldwide"
          ? "Open to applicants worldwide. Working hours and employment arrangements are agreed with the team."
          : location === "Europe"
            ? "You must be based in Europe. Remote refers to where you work, not worldwide eligibility."
            : location === "EU"
              ? "You must be based in an EU member state. The UK is not included in this eligibility region."
              : `You must be based in ${location === "USA" ? "the United States" : location === "UK" ? "the United Kingdom" : location === "Other" ? city : location}. ${workType === "Hybrid" ? "Regular office attendance is required." : workType === "On-site" ? "This role is based in the office." : "This remote role has a geographic restriction."}`;
      return {
        id: `job-${index + 1}`,
        slug: `${name}-${title}`
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/-$/, ""),
        title,
        company: {
          name,
          initials,
          color,
          background,
          description: companyDescription,
          website,
        },
        category,
        location,
        city: city || undefined,
        workType,
        experience,
        salary: min ? { min, max, currency } : undefined,
        technologies: tech,
        firstSeenAt: new Date(now).toISOString(),
        sourceUrl: website,
        publishedAt: new Date(now - hours * 3600000).toISOString(),
        shortDescription: preview,
        description: [
          preview,
          `As a ${title.toLowerCase()} at ${name}, you will work with a small, cross-functional team that values clear thinking, thoughtful execution, and a sustainable pace. You will have space to shape your work and a direct connection to the people using what you build.`,
        ],
        responsibilities: workByCategory[category],
        requirements: [
          `${experience === "Junior" ? "Foundational knowledge and a portfolio or practical projects" : "Practical professional experience"} in ${category.toLowerCase()}.`,
          `Confidence working with ${tech.slice(0, 2).join(" and ")}.`,
          "Clear written communication and a collaborative approach to solving problems.",
          "Care for quality, accessibility, and the experience of the end user.",
        ],
        niceToHave: [
          `Experience with ${tech[2] ?? "cross-functional teams"}.`,
          "Experience working with an international or distributed team.",
        ],
        benefits: [
          "Flexible working hours with time for focused work",
          "Learning and professional development budget",
          "Paid time off and a supportive team culture",
        ],
        eligibility,
        applyUrl: website,
      };
    },
  );
}

// Keep one request-scoped clock for SSR and client filtering to avoid hydration drift.
export function getMockSnapshot() {
  const now = Date.now();
  return { now, jobs: getMockJobs(now) };
}
